//! 🎯️ Actual receipts gate input admission, semantic work, failure publication and byte handback.
use semio_framework_actor::{OriginalJobCallFailure,OriginalJobOutcome,OriginalJobOutputState,RetainedTurnInput};
use crate::original_actor_context::{OriginalActorFixedCall,OriginalActorFixedKind,OriginalOwnedJobCall,OriginalOwnedJobStatus};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum ColdJobAction{AdmitActor,AdmitInput,Start,Step,Read,BorrowChunk,AcknowledgeChunk,AcknowledgeOutput,PublishFailure,ReadFailure,BorrowFailureChunk,AcknowledgeFailureChunk,AcknowledgeFailure,CloseJobs,CloseActorOutput,CloseActor,Complete}
impl ColdJobAction{pub fn label(self)->&'static str{match self{Self::AdmitActor=>"admit-actor",Self::AdmitInput=>"admit-input",Self::Start=>"start",Self::Step=>"step",Self::Read=>"read",Self::BorrowChunk=>"borrow-chunk",Self::AcknowledgeChunk=>"acknowledge-chunk",Self::AcknowledgeOutput=>"acknowledge-output",Self::PublishFailure=>"publish-failure",Self::ReadFailure=>"read-failure",Self::BorrowFailureChunk=>"borrow-failure-chunk",Self::AcknowledgeFailureChunk=>"acknowledge-failure-chunk",Self::AcknowledgeFailure=>"acknowledge-failure",Self::CloseJobs=>"close-jobs",Self::CloseActorOutput=>"close-actor-output",Self::CloseActor=>"close-actor",Self::Complete=>"complete"}}}
#[derive(Clone,Copy,Debug)]
pub enum ColdJobRefusal{Identity,Epoch,Phase,Extent,Original(OriginalJobCallFailure)}
pub struct ColdJobFrontier{job:u64,operation:u64,generation:u64,epoch:u64,maximum:usize,action:ColdJobAction,length:usize,received:usize,chunk:usize,failed:bool,failure_route:bool,marker:Option<OriginalJobCallFailure>}
impl ColdJobFrontier{
 pub fn new(job:u64,operation:u64,generation:u64,maximum:usize)->Result<Self,ColdJobRefusal>{if job==0||operation==0||generation==0{return Err(ColdJobRefusal::Identity)}Ok(Self{job,operation,generation,epoch:0,maximum,action:ColdJobAction::AdmitActor,length:0,received:0,chunk:0,failed:false,failure_route:false,marker:None})}
 pub fn action(&self)->ColdJobAction{self.action}
 pub fn failed(&self)->bool{self.failed}
 pub fn failure_route(&self)->bool{self.failure_route}
 pub fn failure_marker(&self)->Option<OriginalJobCallFailure>{self.marker}
 pub fn output_length(&self)->usize{self.length}
 pub fn chunk(&self)->(usize,usize){(self.received,self.chunk)}
 fn input(&self,input:RetainedTurnInput)->Result<(),ColdJobRefusal>{if(input.operation,input.generation)!=(self.operation,self.generation){return Err(ColdJobRefusal::Identity)}if input.epoch<=self.epoch{return Err(ColdJobRefusal::Epoch)}Ok(())}
 fn failure(&mut self,input:RetainedTurnInput,marker:OriginalJobCallFailure)->Result<(),ColdJobRefusal>{if self.failure_route||matches!(self.action,ColdJobAction::Complete){return Err(ColdJobRefusal::Original(marker))}self.epoch=input.epoch;self.marker=Some(marker);self.failure_route=true;self.failed=true;self.length=0;self.received=0;self.chunk=0;self.action=ColdJobAction::PublishFailure;Ok(())}
 pub fn receive_actor(&mut self,call:OriginalActorFixedCall)->Result<(),ColdJobRefusal>{self.input(call.input)?;if let OriginalActorFixedKind::InputAdmission{ready,input_returned,refusal}=call.kind{if self.action!=ColdJobAction::AdmitInput||ready&&!input_returned{return Err(ColdJobRefusal::Phase)}if !input_returned{if let Some(kind)=refusal{self.marker=Some(OriginalJobCallFailure::Authority(kind));self.failed=true;}self.epoch=call.input.epoch;return Ok(())}if ready&&refusal.is_none()&&self.marker.is_none(){self.epoch=call.input.epoch;self.action=ColdJobAction::Start;return Ok(())}let marker=refusal.map(OriginalJobCallFailure::Authority).or(self.marker).ok_or(ColdJobRefusal::Phase)?;return self.failure(call.input,marker)}if let OriginalActorFixedKind::Failure{authority}=call.kind{return self.failure(call.input,authority.map(OriginalJobCallFailure::Authority).unwrap_or(OriginalJobCallFailure::Semantic))}let next=match(self.action,call.kind){(ColdJobAction::AdmitActor,OriginalActorFixedKind::Admission{ready,refusal:None})=>if ready{ColdJobAction::AdmitInput}else{self.action},(ColdJobAction::CloseActorOutput,OriginalActorFixedKind::Close{complete,blocked,refusal:None})if!complete||!blocked=>if complete{ColdJobAction::CloseActor}else{self.action},(ColdJobAction::CloseActor,OriginalActorFixedKind::Close{complete,blocked,refusal:None})if!complete||!blocked=>if complete{ColdJobAction::Complete}else{self.action},(_,OriginalActorFixedKind::Admission{refusal:Some(kind),..}|OriginalActorFixedKind::Close{refusal:Some(kind),..})=>return self.failure(call.input,OriginalJobCallFailure::Authority(kind)),_=>return Err(ColdJobRefusal::Phase)};self.epoch=call.input.epoch;self.action=next;Ok(())}
 pub fn receive_job(&mut self,call:OriginalOwnedJobCall)->Result<(),ColdJobRefusal>{self.input(call.input)?;if let Some(refusal)=call.refusal{if self.action==ColdJobAction::Start&&!matches!(call.status,OriginalOwnedJobStatus::Start{admitted:false,returned_source:true}){return Err(ColdJobRefusal::Phase)}return self.failure(call.input,refusal)}let next=match(self.action,call.status){
  (ColdJobAction::Start,OriginalOwnedJobStatus::Start{admitted,returned_source})=>match(admitted,returned_source){(true,false)=>ColdJobAction::Step,(false,true)=>self.action,_=>return Err(ColdJobRefusal::Phase)},
  (ColdJobAction::Step|ColdJobAction::PublishFailure,OriginalOwnedJobStatus::Step{outcome:None,..})=>self.action,
  (ColdJobAction::Step|ColdJobAction::PublishFailure,OriginalOwnedJobStatus::Step{outcome:Some(outcome),..})=>{if self.failure_route&&!matches!(outcome.state,OriginalJobOutputState::Failed){return Err(ColdJobRefusal::Phase)}self.outcome(outcome)?;if matches!(outcome.state,OriginalJobOutputState::Running){self.action}else{self.read_action()}},
  (ColdJobAction::Read|ColdJobAction::ReadFailure,OriginalOwnedJobStatus::Output{chunk:Some(chunk),..})=>{if chunk.offset!=self.received as u64{return Err(ColdJobRefusal::Extent)}if chunk.output_closed{if self.received!=self.length||chunk.byte_length.is_some_and(|length|length!=0){return Err(ColdJobRefusal::Extent)}if self.failure_route{ColdJobAction::AcknowledgeFailure}else{ColdJobAction::AcknowledgeOutput}}else if let Some(length)=chunk.byte_length{let length=usize::try_from(length).map_err(|_|ColdJobRefusal::Extent)?;if length>self.length-self.received{return Err(ColdJobRefusal::Extent)}self.chunk=length;if length==0{self.action}else if self.failure_route{ColdJobAction::BorrowFailureChunk}else{ColdJobAction::BorrowChunk}}else{self.action}},
  (ColdJobAction::Read|ColdJobAction::ReadFailure,OriginalOwnedJobStatus::Output{chunk:None,..})=>self.action,
  (ColdJobAction::AcknowledgeChunk|ColdJobAction::AcknowledgeFailureChunk,OriginalOwnedJobStatus::Acknowledge{acknowledged,..})=>if acknowledged{self.received=self.received.checked_add(self.chunk).filter(|length|*length<=self.length).ok_or(ColdJobRefusal::Extent)?;self.chunk=0;self.read_action()}else{self.action},
  (ColdJobAction::AcknowledgeOutput|ColdJobAction::AcknowledgeFailure,OriginalOwnedJobStatus::Acknowledge{acknowledged,..})=>if acknowledged{ColdJobAction::CloseJobs}else{self.action},
  (ColdJobAction::CloseJobs,OriginalOwnedJobStatus::Close{admitted})=>if admitted{ColdJobAction::CloseActorOutput}else{self.action},
  _=>return Err(ColdJobRefusal::Phase)
 };self.epoch=call.input.epoch;self.action=next;Ok(())}
 fn read_action(&self)->ColdJobAction{if self.failure_route{ColdJobAction::ReadFailure}else{ColdJobAction::Read}}
 fn outcome(&mut self,outcome:OriginalJobOutcome)->Result<(),ColdJobRefusal>{if(outcome.job,outcome.operation,outcome.generation)!=(self.job,self.operation,self.generation){return Err(ColdJobRefusal::Identity)}if !matches!(outcome.state,OriginalJobOutputState::Running){let length=usize::try_from(outcome.byte_length).map_err(|_|ColdJobRefusal::Extent)?;if length>self.maximum{return Err(ColdJobRefusal::Extent)}self.length=length;self.failed=matches!(outcome.state,OriginalJobOutputState::Failed);}Ok(())}
 pub fn copied(&mut self)->Result<(),ColdJobRefusal>{if !matches!(self.action,ColdJobAction::BorrowChunk|ColdJobAction::BorrowFailureChunk)||self.chunk==0{return Err(ColdJobRefusal::Phase)}self.action=if self.failure_route{ColdJobAction::AcknowledgeFailureChunk}else{ColdJobAction::AcknowledgeChunk};Ok(())}
}

#[cfg(test)]
mod tests{
 use super::*;use semio_framework_actor::OriginalActorTurnWork;use crate::original_actor_context::OriginalOwnedJobChunk;
 #[test]
 fn portable_frontier_respects_protocol_events_before_output_ack(){
  let fixture:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let job=fixture["job"].as_u64().unwrap();let operation=fixture["operation"].as_u64().unwrap();let generation=fixture["generation"].as_u64().unwrap();
  for row in fixture["cases"].as_array().unwrap(){let mut flow=ColdJobFrontier::new(job,operation,generation,fixture["maximumPayloadBytes"].as_u64().unwrap()as usize).unwrap();for(index,step)in row["steps"].as_array().unwrap().iter().enumerate(){let input=RetainedTurnInput{operation,generation,epoch:index as u64+1,work:OriginalActorTurnWork{clock_binding:1871,absolute_deadline_us:1000000,fuel:1000},grant:semio_framework_value::RetainedCloneGrant{maximum_items:100,maximum_copy_bytes:10000,maximum_capacity_bytes:10000,maximum_release_bytes:10000,maximum_depth:64}};let event=step["event"].as_str().unwrap();let length=step["length"].as_u64().unwrap_or(0);let previous_range=flow.chunk();let result=if event=="copied"{let range=flow.chunk();let result=flow.copied();assert_eq!(flow.chunk(),range);result}else if event.starts_with("actor-")||event.starts_with("input-")||event.starts_with("close-output-"){let kind=match event{"actor-pending"|"actor-ready"=>OriginalActorFixedKind::Admission{ready:event=="actor-ready",refusal:None},"input-pending"|"input-ready"=>OriginalActorFixedKind::InputAdmission{ready:event=="input-ready",input_returned:event=="input-ready",refusal:None},"actor-close-pending"|"actor-closed"|"close-output-pending"|"close-output-closed"=>OriginalActorFixedKind::Close{complete:event=="actor-closed"||event=="close-output-closed",blocked:false,refusal:None},_=>unreachable!()};flow.receive_actor(OriginalActorFixedCall{input,spent:Default::default(),work_units_spent:0,kind})}else{let status=match event{"close-jobs-pending"|"close-jobs-closed"=>OriginalOwnedJobStatus::Close{admitted:event=="close-jobs-closed"},"semantic-refusal"|"failure-pending"=>OriginalOwnedJobStatus::Step{outcome:None,source_closed:false},"start-pending"|"start-ready"=>OriginalOwnedJobStatus::Start{admitted:event=="start-ready",returned_source:event=="start-pending"},"running"|"done"|"failed"|"failure-published"=>OriginalOwnedJobStatus::Step{outcome:Some(OriginalJobOutcome{job,operation,generation,state:match event{"running"=>OriginalJobOutputState::Running,"done"=>OriginalJobOutputState::Done,_=>OriginalJobOutputState::Failed},byte_length:length}),source_closed:false},"chunk"|"failure-chunk"=>OriginalOwnedJobStatus::Output{chunk:Some(OriginalOwnedJobChunk{offset:step["offset"].as_u64().unwrap(),byte_length:Some(length),output_closed:false}),source_closed:false},"output-closed"|"failure-output-closed"=>OriginalOwnedJobStatus::Output{chunk:Some(OriginalOwnedJobChunk{offset:flow.chunk().0 as u64,byte_length:None,output_closed:true}),source_closed:false},"chunk-ack-pending"|"failure-chunk-ack-pending"|"chunk-acknowledged"|"output-acknowledged"|"failure-chunk-acknowledged"|"failure-acknowledged"=>OriginalOwnedJobStatus::Acknowledge{acknowledged:event!="chunk-ack-pending"&&event!="failure-chunk-ack-pending",source_closed:false},_=>unreachable!()};flow.receive_job(OriginalOwnedJobCall{input,spent:Default::default(),work_units_spent:0,status,refusal:if event=="semantic-refusal"{Some(OriginalJobCallFailure::Semantic)}else{None}})};if step["next"]=="refused"{assert!(result.is_err(),"{row:?}");break}result.unwrap();if event=="chunk-ack-pending"||event=="failure-chunk-ack-pending"{assert_eq!(flow.chunk(),previous_range);}assert_eq!(flow.action().label(),step["next"].as_str().unwrap());}if row["id"]=="failed-job-keeps-original-output"{assert!(flow.failed());}}
 }

 #[test]
 fn start_receipts_preserve_the_actual_guest_source(){
  let rows:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
  for row in rows["startCases"].as_array().unwrap(){let mut flow=ColdJobFrontier::new(91,71,3,1024).unwrap();flow.action=ColdJobAction::Start;let input=RetainedTurnInput{operation:71,generation:3,epoch:1,work:OriginalActorTurnWork{clock_binding:1871,absolute_deadline_us:1000000,fuel:1000},grant:semio_framework_value::RetainedCloneGrant{maximum_items:100,maximum_copy_bytes:10000,maximum_capacity_bytes:10000,maximum_release_bytes:10000,maximum_depth:64}};let call=OriginalOwnedJobCall{input,spent:Default::default(),work_units_spent:0,status:OriginalOwnedJobStatus::Start{admitted:row["admitted"].as_bool().unwrap(),returned_source:row["returnedSource"].as_bool().unwrap()},refusal:if row["refusal"].as_bool().unwrap(){Some(OriginalJobCallFailure::Semantic)}else{None}};let result=flow.receive_job(call);if row["next"]=="refused"{assert!(result.is_err())}else{result.unwrap();assert_eq!(flow.action().label(),row["next"].as_str().unwrap());}}
 }
}
